fn encode_cyclic(s: Vec<i8>) -> Vec<i8> {
    let mut result = Vec::with_capacity(s.len());

    // Process each consecutive block of up to 3 elements
    for chunk in s.chunks(3) {
        match chunk {
            // If we have exactly three elements [a, b, c],
            // we cyclically shift left to [b, c, a].
            [a, b, c] => {
                result.push(*b);
                result.push(*c);
                result.push(*a);
            }
            // Otherwise, chunk.len() is 1 or 2; we leave them unchanged.
            rest => {
                result.extend_from_slice(rest);
            }
        }
    }

    result
}

